import React, { useEffect, useMemo, useState } from 'react';
import { createRoot } from 'react-dom/client';
import { LayoutDashboard, History, GraduationCap, Handshake, Landmark, CalendarDays, ListTodo, Target, ShieldAlert, ClipboardCheck, Search, Download, Upload, Plus, Menu, X, ChevronRight, ArrowUpRight, CircleHelp, CheckCircle2, Clock3, AlertTriangle, Save, Filter, ExternalLink, RefreshCw } from 'lucide-react';
import { BarChart, Bar, XAxis, YAxis, Tooltip, ResponsiveContainer, CartesianGrid, PieChart, Pie, Cell, LineChart, Line, Legend } from 'recharts';
import source from './data.json';
import './style.css';

type Row = Record<string, any>;
type Task = Row & { _id:string; _front:string; _source:string };
const STORAGE='fejepar-presex-2027-v1';
const palette=['#01AB97','#F29A32','#0A2A36','#77C9BD','#E5A1A1'];
const fronts:any={ies:'Ensino Superior',market:'Mercado',gov:'Relações Institucionais e Governamentais'};
const nav=[
 {id:'overview',label:'Visão executiva',icon:LayoutDashboard,group:'ESTRATÉGIA'},
 {id:'history',label:'Diagnóstico histórico',icon:History,group:'ESTRATÉGIA'},
 {id:'ies',label:'Ensino Superior',icon:GraduationCap,group:'FRENTES'},
 {id:'market',label:'Mercado',icon:Handshake,group:'FRENTES'},
 {id:'gov',label:'Relações governamentais',icon:Landmark,group:'FRENTES'},
 {id:'calendar',label:'Calendário 2027',icon:CalendarDays,group:'EXECUÇÃO'},
 {id:'roadmaps',label:'Roadmaps operacionais',icon:ListTodo,group:'EXECUÇÃO'},
 {id:'indicators',label:'Indicadores e metas',icon:Target,group:'EXECUÇÃO'},
 {id:'risks',label:'Riscos e capacidade',icon:ShieldAlert,group:'GOVERNANÇA'},
 {id:'governance',label:'Governança e prestação de contas',icon:ClipboardCheck,group:'GOVERNANÇA'},
 {id:'sources',label:'Fontes e auditoria',icon:CircleHelp,group:'SISTEMA'}
];
const money=(n:number)=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(n||0);
const fmtDate=(v:any)=>v?new Date(String(v).slice(0,10)+'T12:00:00').toLocaleDateString('pt-BR'):'A definir';
const statusColor=(s:string)=>s==='Concluído'?'green':s==='Em andamento'?'teal':s==='Atrasado'||s==='Bloqueado'?'red':'gray';
function readState(){
 try{return JSON.parse(localStorage.getItem(STORAGE)||'{}')}catch{return {}}
}
function App(){
 const [page,setPage]=useState('overview'),[mobileOpen,setMobileOpen]=useState(false),[mode,setMode]=useState<'public'|'management'>('public');
 const [persist,setPersist]=useState(readState),[search,setSearch]=useState(''),[frontFilter,setFrontFilter]=useState('Todas'),[statusFilter,setStatusFilter]=useState('Todos'),[month,setMonth]=useState(0);
 const [notice,setNotice]=useState(''),[newTaskOpen,setNewTaskOpen]=useState(false);
 useEffect(()=>{try{localStorage.setItem(STORAGE,JSON.stringify(persist));setNotice('Alterações salvas neste navegador');const t=setTimeout(()=>setNotice(''),2200);return()=>clearTimeout(t)}catch{setNotice('Não foi possível salvar localmente. Exporte os dados.')}},[persist]);
 const tasks:Task[]=useMemo(()=>[...['ies','market','gov'].flatMap(k=>(source as any)[k].roadmap.map((r:Row,i:number)=>({...r,...(persist.tasks||{})[`${k}-${r['Código']}`],_id:`${k}-${r['Código']||i}`,_front:fronts[k],_source:k}))),...(persist.customTasks||[])],[persist]);
 const filteredTasks=tasks.filter(t=>(frontFilter==='Todas'||t._front===frontFilter)&&(statusFilter==='Todos'||t.Status===statusFilter)&&(`${t['Atividade / entrega']} ${t['Etapa / ciclo']} ${t.Responsável} ${t._front}`).toLowerCase().includes(search.toLowerCase()));
 const done=tasks.filter(t=>t.Status==='Concluído').length, running=tasks.filter(t=>t.Status==='Em andamento').length, blocked=tasks.filter(t=>['Atrasado','Bloqueado'].includes(t.Status)).length;
 const progress=Math.round(done/Math.max(tasks.length,1)*100);
 const setTask=(id:string,patch:Row)=>setPersist((p:any)=>({...p,tasks:{...(p.tasks||{}),[id]:{...((p.tasks||{})[id]||{}),...patch}}}));
 const exportData=()=>{const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),tasks,records:persist},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='fejepar-presex-2027-dados.json';a.click();URL.revokeObjectURL(a.href)};
 const exportCSV=()=>{const headers=['Código','Frente','Etapa / ciclo','Atividade / entrega','Responsável','Início','Fim','Prioridade','Status','Entregável / evidência','Dependências / observações'];const rows=filteredTasks.map(t=>[t['Código'],t._front,t['Etapa / ciclo'],t['Atividade / entrega'],t.Responsável,t.Início,t.Fim,t.Prioridade,t.Status,t['Entregável / evidência'],t['Dependências / observações']]);const csv=[headers,...rows].map(r=>r.map(v=>`"${String(v??'').replaceAll('"','""')}"`).join(';')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv;charset=utf-8;'}));a.download='roadmap-fejepar-2027.csv';a.click();URL.revokeObjectURL(a.href)};
 const importJSON=(e:React.ChangeEvent<HTMLInputElement>)=>{const file=e.target.files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>{try{const parsed=JSON.parse(String(reader.result));setPersist(parsed.records||parsed);setNotice('Arquivo importado com sucesso')}catch{setNotice('Arquivo inválido. Use um JSON exportado pelo dashboard.')}};reader.readAsText(file)};
 const go=(id:string)=>{setPage(id);setMobileOpen(false);setSearch('');setFrontFilter('Todas');setStatusFilter('Todos')};
 const currentTitle=nav.find(n=>n.id===page)?.label||'Visão executiva';
 return <div className="app">
  <aside className={`sidebar ${mobileOpen?'open':''}`}>
   <div className="brand"><div className="brand-mark">F</div><div><b>FEJEPAR</b><span>PRESEX 2027</span></div><button className="close-mobile" onClick={()=>setMobileOpen(false)} aria-label="Fechar menu"><X size={18}/></button></div>
   <div className="candidate"><span className="eyebrow">CANDIDATURA À PRESIDÊNCIA EXECUTIVA</span><strong>João Vitor de Souza Ribeiro</strong><span className="candidate-status"><span/> Planejamento estratégico 2027</span></div>
   {['ESTRATÉGIA','FRENTES','EXECUÇÃO','GOVERNANÇA','SISTEMA'].map(g=><div className="nav-group" key={g}><div className="nav-label">{g}</div>{nav.filter(n=>n.group===g).map(n=><button key={n.id} className={`nav-item ${page===n.id?'active':''}`} onClick={()=>go(n.id)}><n.icon size={17}/><span>{n.label}</span>{page===n.id&&<ChevronRight size={14} className="nav-chevron"/>}</button>)}</div>)}
   <div className="sidebar-bottom"><div className="side-note"><span className="dot"/> Projeto de gestão <b>2027</b><small>Estratégia · Pessoas · Execução</small></div><span className="version">Versão de trabalho · v1.0</span></div>
  </aside>
  {mobileOpen&&<div className="scrim" onClick={()=>setMobileOpen(false)}/>}
  <main className="main">
   <header className="topbar"><button className="mobile-menu" onClick={()=>setMobileOpen(true)} aria-label="Abrir menu"><Menu/></button><div className="crumb">FEJEPAR <ChevronRight size={13}/> <span>{currentTitle}</span></div><div className="top-actions"><div className="mode-switch"><button className={mode==='public'?'selected':''} onClick={()=>setMode('public')}>Apresentação</button><button className={mode==='management'?'selected':''} onClick={()=>setMode('management')}>Gestão local</button></div><button className="icon-btn" title="Exportar dados" onClick={exportData}><Download size={17}/></button></div></header>
   <div className="page-wrap">
    {mode==='management'&&<div className="management-banner"><AlertTriangle size={17}/><div><b>Modo de gestão local</b><span>Dados e alterações ficam neste navegador. Não há autenticação nem sincronização entre usuários. Não insira informações pessoais sensíveis neste ambiente.</span></div><label className="import-button"><Upload size={15}/> Importar JSON<input type="file" accept=".json,application/json" onChange={importJSON}/></label></div>}
    {page==='overview'&&<Overview tasks={tasks} done={done} running={running} blocked={blocked} progress={progress} go={go}/>}
    {page==='history'&&<HistoryPage/>}
    {['ies','market','gov'].includes(page)&&<FrontPage kind={page} tasks={tasks.filter(t=>t._source===page)} portfolio={(source as any)[page].portfolio} go={go} mode={mode} persist={persist} setPersist={setPersist}/>}
    {page==='calendar'&&<CalendarPage tasks={tasks} month={month} setMonth={setMonth} go={go}/>}
    {page==='roadmaps'&&<RoadmapPage tasks={filteredTasks} allTasks={tasks} search={search} setSearch={setSearch} frontFilter={frontFilter} setFrontFilter={setFrontFilter} statusFilter={statusFilter} setStatusFilter={setStatusFilter} setTask={setTask} exportCSV={exportCSV} mode={mode} onNew={()=>setNewTaskOpen(true)}/>}
    {page==='indicators'&&<IndicatorsPage/>}
    {page==='risks'&&<RisksPage mode={mode} persist={persist} setPersist={setPersist}/>}
    {page==='governance'&&<GovernancePage mode={mode} persist={persist} setPersist={setPersist}/>}
    {page==='sources'&&<SourcesPage/>}
   </div>
   <footer><span>FEJEPAR PresEx 2027 · Estratégia integrada, execução acompanhada.</span><span>{notice||'Dados de origem: proposta eleitoral e roadmaps anexados'}</span></footer>
  </main>
  {newTaskOpen&&<NewTaskModal onClose={()=>setNewTaskOpen(false)} onSave={(task:any)=>{setPersist((p:any)=>({...p,customTasks:[...(p.customTasks||[]),task]}));setNewTaskOpen(false);setNotice('Atividade local criada')}}/>}
 </div>
}
function PageHead({kicker,title,desc,action}:any){return <div className="page-head"><div><div className="eyebrow">{kicker}</div><h1>{title}</h1><p>{desc}</p></div>{action}</div>}
function Stat({label,value,sub,icon:Icon,tone='teal'}:any){return <div className="stat-card"><div className={`stat-icon ${tone}`}><Icon size={18}/></div><div className="stat-label">{label}</div><div className="stat-value">{value}</div><div className="stat-sub">{sub}</div></div>}
function SectionTitle({title,desc,right}:any){return <div className="section-title"><div><h2>{title}</h2>{desc&&<p>{desc}</p>}</div>{right}</div>}
function Overview({tasks,done,running,blocked,progress,go}:any){
 const monthly=[{m:'Jan',n:7},{m:'Fev',n:10},{m:'Mar',n:8},{m:'Abr',n:6},{m:'Mai',n:5},{m:'Jun',n:5},{m:'Jul',n:4},{m:'Ago',n:5},{m:'Set',n:4},{m:'Out',n:4},{m:'Nov',n:5},{m:'Dez',n:5}];
 const frontStats=['ies','market','gov'].map(k=>({key:k,name:fronts[k],count:tasks.filter((t:Task)=>t._source===k).length,done:tasks.filter((t:Task)=>t._source===k&&t.Status==='Concluído').length}));
 return <><div className="hero"><div className="hero-content"><div className="hero-label"><span className="hero-dot"/> PLANEJAMENTO ESTRATÉGICO · 2027</div><h1>Relacionamentos que<br/><em>se transformam em resultados.</em></h1><p>A PresEx integra estratégia, pessoas e execução para transformar articulações em resultados sustentáveis para a FEJEPAR e para as Empresas Juniores do Paraná.</p><div className="hero-actions"><button className="btn-primary" onClick={()=>go('roadmaps')}>Acompanhar execução <ArrowUpRight size={16}/></button><button className="btn-ghost" onClick={()=>go('indicators')}>Explorar indicadores</button></div></div><div className="hero-art"><div className="orbit orbit1"/><div className="orbit orbit2"/><div className="orbit orbit3"/><div className="core">F<span>+</span></div><div className="orbit-label ol1">IES</div><div className="orbit-label ol2">MERCADO</div><div className="orbit-label ol3">GOVERNO</div></div></div>
 <div className="stat-grid"><Stat label="Atividades no roadmap" value={tasks.length} sub="3 frentes · 2027" icon={ListTodo}/><Stat label="Concluídas" value={done} sub={`${progress}% do total planejado`} icon={CheckCircle2} tone="green"/><Stat label="Em andamento" value={running} sub="Status conforme planilhas de origem" icon={Clock3} tone="orange"/><Stat label="Atrasadas ou bloqueadas" value={blocked} sub="Atualize o status no modo gestão" icon={AlertTriangle} tone="red"/></div>
 <div className="section-gap"><SectionTitle title="Apostas estratégicas de 2027" desc="Três frentes complementares, conectadas pela governança da PresEx."/><div className="bets-grid">{[{num:'01',k:'ies',title:'Ensino Superior',desc:'Aproximar as IES para potencializar a rede paranaense.',method:'Jornada Regional de Relacionamento',outcome:'Cooperações executadas e benefícios para as EJs',color:'teal',icon:GraduationCap},{num:'02',k:'market',title:'Mercado',desc:'Diversificar receitas e construir parcerias de valor.',method:'Value Proposition Canvas',outcome:'Receita diversificada e benefícios à rede',color:'orange',icon:Handshake},{num:'03',k:'gov',title:'Relações Institucionais e Governamentais',desc:'Institucionalizar relações e ampliar oportunidades.',method:'Planejamento de Public Affairs',outcome:'Articulação contínua e avanços verificáveis',color:'blue',icon:Landmark}].map(b=><button className={`bet-card ${b.color}`} key={b.k} onClick={()=>go(b.k)}><div className="bet-top"><span>{b.num}</span><b.icon size={21}/><ArrowUpRight size={16}/></div><h3>{b.title}</h3><p>{b.desc}</p><div className="bet-method"><small>METODOLOGIA</small><b>{b.method}</b></div><div className="bet-outcome"><CheckCircle2 size={15}/>{b.outcome}</div></button>)}</div></div>
 <div className="two-col section-gap"><div className="panel"><SectionTitle title="Execução dos roadmaps" desc="Distribuição atual de atividades por frente."/><div className="front-bars">{frontStats.map((f:any,i:number)=><div className="front-bar-row" key={f.key}><div className="bar-label"><span className={`bar-dot d${i}`}/><b>{f.name}</b><span>{f.done}/{f.count}</span></div><div className="progress-track"><div style={{width:`${f.count?f.done/f.count*100:0}%`}} className={`progress-fill p${i}`}/></div></div>)}</div><button className="text-link" onClick={()=>go('roadmaps')}>Ver todos os roadmaps <ChevronRight size={15}/></button></div>
 <div className="panel"><SectionTitle title="O que queremos construir" desc="Resultados esperados ao longo da gestão."/><div className="outcome-list"><div><span className="outcome-icon teal"><GraduationCap size={17}/></span><p><b>Para as IES</b><small>Relações acompanhadas, cooperações formalizadas e compromissos executados.</small></p></div><div><span className="outcome-icon orange"><Handshake size={17}/></span><p><b>Para o mercado</b><small>Propostas validadas, parcerias recorrentes e contrapartidas entregues.</small></p></div><div><span className="outcome-icon blue"><Landmark size={17}/></span><p><b>Para a rede</b><small>Agendas institucionais, encaminhamentos acompanhados e oportunidades documentadas.</small></p></div></div></div></div>
 <div className="two-col section-gap"><div className="panel"><SectionTitle title="Diagnóstico que orienta 2027" desc="O padrão que se repete no triênio."/><div className="pattern"><div><span>01</span><b>Mobilizar</b><small>Construir relações e abrir oportunidades.</small></div><ChevronRight/><div><span>02</span><b>Estruturar</b><small>Formalizar compromissos e definir responsáveis.</small></div><ChevronRight/><div><span>03</span><b>Sustentar</b><small>Acompanhar entregas e garantir continuidade.</small></div></div><p className="callout">O desafio central não é a ausência de iniciativas, mas garantir continuidade, equilíbrio entre frentes e conversão das articulações em resultados recorrentes.</p><button className="text-link" onClick={()=>go('history')}>Ler diagnóstico histórico <ChevronRight size={15}/></button></div>
 <div className="panel"><SectionTitle title="Marcos do calendário" desc="Janelas indicativas — confirmar datas oficiais."/><div className="milestone-list"><div><div className="date-chip">MAR</div><p><b>EDL Paranaense</b><small>Articulação de apoios e oportunidades institucionais.</small></p><span className="tag estimated">Estimado</span></div><div><div className="date-chip">JUL–SET</div><p><b>ENEJ</b><small>Planejamento de articulação e acompanhamento de apoios.</small></p><span className="tag estimated">Janela</span></div><div><div className="date-chip">DEZ</div><p><b>Prêmio FEJEPAR</b><small>Articulação, apoios e registro de contrapartidas.</small></p><span className="tag estimated">Estimado</span></div></div><button className="text-link" onClick={()=>go('calendar')}>Abrir calendário anual <ChevronRight size={15}/></button></div></div>
 <div className="capacity-note"><ShieldAlert size={18}/><div><b>Execução dimensionada à capacidade real</b><p>Vacâncias, sobrecarga, pressão do ENEJ e concentração de receitas exigem priorização, documentação e revisão periódica do escopo.</p></div><button onClick={()=>go('risks')}>Ver riscos <ChevronRight size={15}/></button></div>
 </>;
}
function HistoryPage(){return <><PageHead kicker="ESTRATÉGIA · BASE HISTÓRICA" title="O que aprendemos com o triênio" desc="Resultados registrados na proposta eleitoral e desafios que orientam as prioridades de 2027."/><div className="timeline">{(source as any).historical.map((h:any,i:number)=><div className="timeline-item" key={h.year}><div className="timeline-year">{h.year}</div><div className="timeline-card"><div className="timeline-head"><h3>{h.title}</h3><span className="tag source">Registro histórico</span></div><p>{h.detail}</p><div className="lesson"><b>Aprendizado para 2027</b><span>{['Ampliar a rede não pode deixar outras relações estratégicas sem acompanhamento.','Relacionamentos geram valor quando há continuidade, compromisso acompanhado e entregas verificáveis.','Formalizar, diversificar e acompanhar os resultados das relações já iniciadas.'][i]}</span></div></div></div>)}</div><div className="panel section-gap"><SectionTitle title="Concentração financeira em eventos e produtos" desc="Participação nas entradas totais, conforme gráfico da proposta eleitoral (p. 3)."/><div className="chart-wrap"><ResponsiveContainer width="100%" height={260}><BarChart data={(source as any).financial.eventShare}><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#e6ecec"/><XAxis dataKey="year"/><YAxis unit="%" domain={[0,100]}/><Tooltip formatter={(v:any)=>`${v}%`}/><Bar dataKey="value" name="Participação" fill="#F29A32" radius={[6,6,0,0]}/></BarChart></ResponsiveContainer></div><p className="source-note">A planilha financeira complementar classifica o grupo como “Eventos e produtos”. Portanto, o indicador deve ser interpretado com esse nome, sem assumir que represente somente eventos.</p></div><div className="three-col section-gap"><div className="insight-card"><span>2024</span><h3>Expansão</h3><p>Alta demanda de expansão concentrou esforços e dificultou o desenvolvimento equilibrado das frentes.</p></div><div className="insight-card"><span>2025</span><h3>Continuidade</h3><p>Relações com UTFPR e UEM produziram apoio concreto, mas houve atrasos e lacunas em outras entregas.</p></div><div className="insight-card"><span>2026</span><h3>Conversão</h3><p>A articulação avançou; o próximo passo é transformar iniciativas em compromissos formalizados e resultados recorrentes.</p></div></div></>}
function FrontPage({kind,tasks,portfolio,go,mode,persist,setPersist}:any){
 const cfg:any={ies:{kicker:'MARCO 01 · ENSINO SUPERIOR',title:'Aproximar as IES para potencializar a rede',desc:'Jornada Regional de Relacionamento com as IES — mapear, conectar, construir, executar e avaliar.',steps:['Mapear','Conectar','Construir','Executar','Avaliar'],method:'Cada etapa gera registros para orientar a próxima, mantendo histórico, responsáveis e continuidade institucional.'},market:{kicker:'MARCO 02 · MERCADO',title:'Diversificar receitas e construir parcerias de valor',desc:'Aplicar o Value Proposition Canvas para conectar necessidades do mercado a soluções que beneficiem a rede.',steps:['Segmentar e diagnosticar','Construir proposta de valor','Validar e negociar','Entregar, avaliar e renovar'],method:'Perfil do parceiro: tarefas, dores e ganhos. Mapa de valor: soluções, aliviadores de dores e criadores de ganhos. O encaixe orienta propostas mutuamente relevantes.'},gov:{kicker:'MARCO 03 · RELAÇÕES INSTITUCIONAIS E GOVERNAMENTAIS',title:'Institucionalizar relações e ampliar oportunidades',desc:'Jornada de Articulação Institucional e Governamental baseada no planejamento de Public Affairs.',steps:['Análise do contexto','Objetivos SMART','Coalizões e alianças','Públicos prioritários','Mensagens-chave','Canais de comunicação','Monitoramento e impacto'],method:'O mapeamento de 88 atores políticos eleitos e as cartas de parabenização de 2026 são uma base inicial citada na proposta; os registros individuais precisam ser importados/validados.'}};
 const c=cfg[kind], allTasks=tasks.length, done=tasks.filter((t:Task)=>t.Status==='Concluído').length;
 const [q,setQ]=useState(''),[stage,setStage]=useState('Todas');
 const [entries,setEntries]=useState<any[]>(()=>((persist.portfolios||{})[kind]||[]));
 useEffect(()=>setEntries(((persist.portfolios||{})[kind]||[])),[persist,kind]);
 const addEntry=()=>{const name=prompt(kind==='ies'?'Nome da instituição (sem dados pessoais desnecessários):':kind==='market'?'Nome do parceiro:':'Nome do ator, órgão ou pauta:');if(!name)return;const entry={id:Date.now(),name,stage:'Mapear',status:'Em prospecção',priority:'Média',next:'A definir pela gestão',due:'',note:''};const next=[...entries,entry];setEntries(next);setPersist((p:any)=>({...p,portfolios:{...(p.portfolios||{}),[kind]:next}}))};
 const updateEntry=(id:number,patch:any)=>{const next=entries.map(e=>e.id===id?{...e,...patch}:e);setEntries(next);setPersist((p:any)=>({...p,portfolios:{...(p.portfolios||{}),[kind]:next}}))};
 const visible=entries.filter(e=>(stage==='Todas'||e.stage===stage)&&e.name.toLowerCase().includes(q.toLowerCase()));
 return <><PageHead kicker={c.kicker} title={c.title} desc={c.desc} action={<button className="btn-secondary" onClick={()=>go('roadmaps')}>Abrir roadmap <ArrowUpRight size={15}/></button>}/>
 <div className="method-flow">{c.steps.map((s:string,i:number)=><React.Fragment key={s}><button className={`method-step ${i===c.steps.length-1?'last':''}`} onClick={()=>{setStage(s);document.getElementById('portfolio')?.scrollIntoView({behavior:'smooth'})}}><span>{String(i+1).padStart(2,'0')}</span><b>{s}</b></button>{i<c.steps.length-1&&<ChevronRight size={15} className="method-arrow"/>}</React.Fragment>)}</div><p className="method-note">{c.method}</p>
 <div className="stat-grid compact"><Stat label="Atividades no roadmap" value={allTasks} sub="Atividades importadas da planilha" icon={ListTodo}/><Stat label="Concluídas" value={done} sub={`${Math.round(done/Math.max(allTasks,1)*100)}% do plano`} icon={CheckCircle2} tone="green"/><Stat label="Registros de carteira" value={entries.length} sub="Registros adicionados no navegador" icon={kind==='ies'?GraduationCap:kind==='market'?Handshake:Landmark}/><Stat label="Rotina de acompanhamento" value="Quinzenal" sub="Conforme rito do roadmap" icon={RefreshCw} tone="orange"/></div>
 {kind==='ies'&&<div className="panel section-gap"><SectionTitle title="Instituições citadas na proposta" desc="Mapa conceitual da página 5; não representa geolocalização nem estágio atualizado."/><div className="institution-grid">{['UTFPR','UNILA','UEM','UFPR','UEL','UNESPAR','IFPR','UEPG','UNIOESTE','PUCPR','UNICENTRO','UENP'].map((x,i)=><div key={x} className={`institution inst${i%4}`}><GraduationCap size={15}/><b>{x}</b><small>{i<2?'Relação citada no diagnóstico':'Instituição listada no mapa da proposta'}</small></div>)}</div><p className="source-note">O PDF não fornece coordenadas nem uma carteira atualizada por instituição. Nenhuma localização geográfica foi inferida.</p></div>}
 {kind==='market'&&<div className="three-col section-gap">{[{title:'Employer Branding',desc:'Conectar empresas aos talentos e às oportunidades presentes no MEJ.'},{title:'Conselho de Mantenedores',desc:'Aproximar parceiros estratégicos e fortalecer contribuições à rede.'},{title:'Soluções do mercado para a rede',desc:'Articular ferramentas, conteúdos e condições especiais para as EJs.'}].map(x=><div className="initiative-card" key={x.title}><span className="initiative-icon"><Handshake size={18}/></span><h3>{x.title}</h3><p>{x.desc}</p></div>)}</div>}
 {kind==='gov'&&<div className="panel section-gap"><SectionTitle title="Os sete passos de Public Affairs" desc="Ciclo por pauta ou interlocutor; pode ser iniciado em qualquer data."/><div className="pa-steps">{c.steps.map((s:string,i:number)=><div key={s}><span>{i+1}</span><b>{s}</b><small>{['Mapear pautas, competências e processos decisórios.','Definir resultados específicos, mensuráveis e temporais.','Identificar organizações com interesses convergentes.','Priorizar atores conforme influência e oportunidade.','Construir argumentos consistentes e baseados em evidências.','Selecionar agendas, ofícios, reuniões e fóruns.','Registrar encaminhamentos e avaliar avanços verificáveis.'][i]}</small></div>)}</div></div>}
 <div className="panel section-gap" id="portfolio"><SectionTitle title={kind==='ies'?'Carteira de relacionamento com IES':kind==='market'?'Pipeline e carteira de parceiros':'Mapa de atores e pautas'} desc="Os registros iniciais das planilhas estão em branco/modelo. Adicione e acompanhe dados locais no modo gestão." right={mode==='management'?<button className="btn-primary small" onClick={addEntry}><Plus size={15}/> Novo registro</button>:<span className="tag estimated">Visualização pública</span>}/><div className="filter-row"><div className="searchbox"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pesquisar registros..."/></div><select value={stage} onChange={e=>setStage(e.target.value)}><option>Todas</option>{c.steps.map((s:string)=><option key={s}>{s}</option>)}</select></div>
 {visible.length===0?<div className="empty-state"><div><Search size={23}/></div><b>Nenhum registro na carteira</b><p>{entries.length?'Tente ajustar os filtros.':'A planilha de origem contém linhas de modelo (“A definir”); não foram importados contatos pessoais nem atores inventados.'}</p>{mode==='management'&&<button className="btn-secondary" onClick={addEntry}><Plus size={15}/> Criar primeiro registro</button>}</div>:<div className="portfolio-list">{visible.map(e=><div className="portfolio-item" key={e.id}><div className="portfolio-avatar">{e.name.slice(0,1).toUpperCase()}</div><div className="portfolio-main"><b>{e.name}</b><span>{e.stage} · {e.status}</span><small>Próximo passo: {e.next||'A definir pela gestão'} {e.due&&`· Prazo: ${fmtDate(e.due)}`}</small></div>{mode==='management'&&<div className="portfolio-controls"><select value={e.stage} onChange={ev=>updateEntry(e.id,{stage:ev.target.value})}>{c.steps.map((s:string)=><option key={s}>{s}</option>)}</select><select value={e.status} onChange={ev=>updateEntry(e.id,{status:ev.target.value})}>{['Em prospecção','Em andamento','Aguardando retorno','Formalizado','Concluído','Suspenso'].map(s=><option key={s}>{s}</option>)}</select><input aria-label="Próximo passo" value={e.next||''} onChange={ev=>updateEntry(e.id,{next:ev.target.value})} placeholder="Próximo passo"/><input aria-label="Prazo" type="date" value={e.due||''} onChange={ev=>updateEntry(e.id,{due:ev.target.value})}/></div>}</div>)}</div>}
 </div><div className="governance-strip"><Clock3 size={17}/><div><b>Ritos de governança da frente</b><p>Revisão quinzenal de contatos e encaminhamentos; revisão mensal da agenda/carteira; revisão trimestral de indicadores e prioridades. Fechamento e transição em novembro–dezembro.</p></div></div></>
}
function CalendarPage({tasks,month,setMonth,go}:any){
 const months=['Janeiro','Fevereiro','Março','Abril','Maio','Junho','Julho','Agosto','Setembro','Outubro','Novembro','Dezembro'];
 const events=[{m:2,title:'EDL Paranaense',detail:'Referência inicial em março; data oficial a confirmar.',kind:'Marco'},{m:6,title:'ENEJ — janela de planejamento',detail:'Janela entre julho e setembro, sujeita à confirmação.',kind:'Marco'},{m:7,title:'ENEJ — janela de planejamento',detail:'Janela entre julho e setembro, sujeita à confirmação.',kind:'Marco'},{m:8,title:'ENEJ — janela de planejamento',detail:'Janela entre julho e setembro, sujeita à confirmação.',kind:'Marco'},{m:11,title:'Prêmio FEJEPAR',detail:'Referência inicial em dezembro; data oficial a confirmar.',kind:'Marco'}];
 const items=[...events.filter(e=>e.m===month),...tasks.filter((t:Task)=>t.Início&&new Date(String(t.Início)+'T12:00:00').getMonth()===month).slice(0,15).map((t:Task)=>({m:month,title:t['Atividade / entrega'],detail:`${t._front} · ${t.Responsável||'A definir pela gestão'}`,kind:'Atividade',task:t}))];
 return <><PageHead kicker="EXECUÇÃO · CALENDÁRIO HÍBRIDO" title="Calendário estratégico 2027" desc="Marcos anuais, rotinas contínuas e ciclos individuais de relacionamento. As datas de eventos são estimativas até confirmação oficial."/><div className="calendar-layout"><div className="panel calendar-panel"><div className="calendar-head"><button className="icon-btn" onClick={()=>setMonth((month+11)%12)} aria-label="Mês anterior">‹</button><h2>{months[month]} <span>2027</span></h2><button className="icon-btn" onClick={()=>setMonth((month+1)%12)} aria-label="Próximo mês">›</button></div><div className="month-grid">{months.map((m,i)=><button key={m} onClick={()=>setMonth(i)} className={month===i?'selected':''}><span>{String(i+1).padStart(2,'0')}</span>{m.slice(0,3)}</button>)}</div><div className="calendar-legend"><span><i className="legend-dot orange-dot"/> Marco estratégico estimado</span><span><i className="legend-dot teal-dot"/> Atividade do roadmap</span></div><div className="year-events">{events.filter(e=>e.m===month).map((e,i)=><div className="year-event" key={e.title+i}><span className="event-marker orange-dot"/><div><b>{e.title}</b><p>{e.detail}</p></div><span className="tag estimated">Estimado</span></div>)}</div></div><div className="panel agenda-panel"><SectionTitle title={`Agenda de ${months[month].toLowerCase()}`} desc={`${items.length} itens na janela mensal (atividades limitadas à visualização).`}/>{items.length===0?<div className="empty-state slim"><b>Nenhum marco fixo neste mês</b><p>As rotinas contínuas e ciclos individuais continuam disponíveis nos roadmaps.</p></div>:<div className="agenda-list">{items.map((e:any,i:number)=><div className="agenda-item" key={i}><div className={`agenda-date ${e.kind==='Marco'?'orange':'teal'}`}>{e.kind==='Marco'?'★':'•'}</div><div><span className="eyebrow">{e.kind}</span><b>{e.title}</b><p>{e.detail}</p>{e.task&&<button className="text-link" onClick={()=>go('roadmaps')}>Ver roadmap <ChevronRight size={14}/></button>}</div></div>)}</div>}</div></div><div className="callout section-gap">As atividades contínuas podem ser iniciadas em qualquer data. O calendário não deve bloquear a entrada de novos parceiros, IES, atores públicos ou pautas.</div></>
}
function RoadmapPage({tasks,allTasks,search,setSearch,frontFilter,setFrontFilter,statusFilter,setStatusFilter,setTask,exportCSV,mode,onNew}:any){
 const [expanded,setExpanded]=useState<string|null>(null);
 return <><PageHead kicker="EXECUÇÃO · PLANOS OPERACIONAIS" title="Roadmaps operacionais" desc="Atividades importadas dos três arquivos de planejamento. Status, responsáveis e datas podem ser atualizados localmente no modo gestão." action={<div className="head-actions"><button className="btn-secondary" onClick={exportCSV}><Download size={15}/> Exportar CSV</button>{mode==='management'&&<button className="btn-primary" onClick={onNew}><Plus size={15}/> Nova atividade</button>}</div>}/><div className="stat-grid compact"><Stat label="Atividades no plano" value={allTasks.length} sub="18 por frente na origem" icon={ListTodo}/><Stat label="Exibidas pelos filtros" value={tasks.length} sub="Resultado atual" icon={Filter}/><Stat label="Concluídas" value={allTasks.filter((t:Task)=>t.Status==='Concluído').length} sub="Conforme status atual" icon={CheckCircle2} tone="green"/><Stat label="Sem responsável definido" value={allTasks.filter((t:Task)=>!t.Responsável||String(t.Responsável).includes('A definir')).length} sub="Verificar alocação" icon={AlertTriangle} tone="orange"/></div><div className="panel section-gap"><div className="filter-row roadmap-filters"><div className="searchbox"><Search size={16}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Buscar atividade, etapa ou responsável..."/></div><select value={frontFilter} onChange={e=>setFrontFilter(e.target.value)}><option>Todas</option>{Object.values(fronts).map((f:any)=><option key={f}>{f}</option>)}</select><select value={statusFilter} onChange={e=>setStatusFilter(e.target.value)}><option>Todos</option>{['Não iniciado','Em andamento','Concluído','Atrasado','Bloqueado'].map(s=><option key={s}>{s}</option>)}</select><button className="icon-btn" onClick={()=>{setSearch('');setFrontFilter('Todas');setStatusFilter('Todos')}} title="Limpar filtros"><RefreshCw size={16}/></button></div><div className="table-meta">Mostrando <b>{tasks.length}</b> de {allTasks.length} atividades · Fonte: abas “Roadmap 2027” das planilhas anexadas</div><div className="table-scroll"><table><thead><tr><th>Código / frente</th><th>Atividade</th><th>Responsável</th><th>Prazo</th><th>Prioridade</th><th>Status</th><th></th></tr></thead><tbody>{tasks.map((t:Task)=><React.Fragment key={t._id}><tr><td><b className="task-code">{t['Código']}</b><small className="table-front">{t._front}</small></td><td><b>{t['Atividade / entrega']}</b><small>{t['Etapa / ciclo']}</small></td><td>{t.Responsável||'A definir pela gestão'}</td><td><span>{fmtDate(t.Início)}</span><small>até {fmtDate(t.Fim)}</small></td><td><span className={`priority ${String(t.Prioridade).toLowerCase()}`}>{t.Prioridade||'A definir'}</span></td><td>{mode==='management'?<select className="status-select" value={t.Status||'Não iniciado'} onChange={e=>setTask(t._id,{Status:e.target.value})}>{['Não iniciado','Em andamento','Concluído','Atrasado','Bloqueado'].map(s=><option key={s}>{s}</option>)}</select>:<span className={`status-pill ${statusColor(t.Status)}`}>{t.Status||'Não iniciado'}</span>}</td><td><button className="icon-btn" onClick={()=>setExpanded(expanded===t._id?null:t._id)} aria-label="Detalhar atividade"><ChevronRight size={16} className={expanded===t._id?'rotate':''}/></button></td></tr>{expanded===t._id&&<tr className="detail-row"><td colSpan={7}><div className="task-detail"><div><b>Entregável / evidência</b><p>{t['Entregável / evidência']||'Não informado na fonte'}</p></div><div><b>Indicador / critério de conclusão</b><p>{t['Indicador / critério de conclusão']||'Não informado na fonte'}</p></div><div><b>Dependências / observações</b><p>{t['Dependências / observações']||'Nenhuma observação registrada'}</p></div>{mode==='management'&&<label className="evidence-field">Observação de acompanhamento<textarea value={t._note||''} onChange={e=>setTask(t._id,{_note:e.target.value})} placeholder="Registre evidências, bloqueios ou encaminhamentos..."/></label>}</div></td></tr>}</React.Fragment>)}</tbody></table>{tasks.length===0&&<div className="empty-state"><b>Nenhuma atividade encontrada</b><p>Altere os filtros para visualizar outras atividades.</p></div>}</div></div><p className="source-note">Datas e responsáveis são reproduzidos das planilhas. A visualização não reordena atividades em uma sequência rígida; os ciclos contínuos permanecem ativos durante o ano.</p></>
}
function IndicatorsPage(){const [f,setF]=useState('Todas'),[q,setQ]=useState('');const items=(source as any).indicators.filter((i:any)=>(f==='Todas'||i.front===f)&&`${i.name} ${i.definition}`.toLowerCase().includes(q.toLowerCase()));return <><PageHead kicker="EXECUÇÃO · MENSURAÇÃO" title="Indicadores e metas" desc="Critérios e metas propostos na proposta eleitoral. Resultados atuais não foram inventados: devem ser preenchidos após a linha de base e durante a gestão."/><div className="callout">Metas propostas não equivalem a resultados alcançados. Os indicadores sem meta numérica validada permanecem “a definir” ou com a cadência indicada na fonte.</div><div className="filter-row section-gap"><div className="searchbox"><Search size={16}/><input value={q} onChange={e=>setQ(e.target.value)} placeholder="Pesquisar indicador..."/></div><select value={f} onChange={e=>setF(e.target.value)}><option>Todas</option>{Object.values(fronts).map((x:any)=><option key={x}>{x}</option>)}</select></div><div className="indicator-grid">{items.map((i:any)=><div className="indicator-card" key={i.name}><div className="indicator-head"><span className={`front-label ${i.front===fronts.ies?'teal':i.front===fronts.market?'orange':'blue'}`}>{i.front}</span><span className="tag source">Meta proposta</span></div><h3>{i.name}</h3><p>{i.definition}</p><div className="indicator-bottom"><div><small>META / CRITÉRIO</small><b>{i.target}</b></div><div><small>RESULTADO ATUAL</small><b className="muted-value">A preencher</b></div></div><div className="indicator-foot"><span>Fonte: proposta eleitoral, pp. 5, 7 e 9</span><span className="tag gray">Sem linha de base</span></div></div>)}</div></>}
function RisksPage({mode,persist,setPersist}:any){const defaults=[{title:'Vacâncias e sobrecarga',detail:'Redistribuição de entregas e revisão do escopo conforme equipe disponível.',mitigation:'Repriorizar entregas essenciais e revisar escopo.',owner:'A definir pela gestão',prob:'Não informada',impact:'Não informado',status:'Monitorar'},{title:'Pressão do ENEJ',detail:'Concentração de esforço no evento pode comprometer outras frentes.',mitigation:'Priorização trimestral e proteção das entregas essenciais.',owner:'A definir pela gestão',prob:'Não informada',impact:'Não informado',status:'Monitorar'},{title:'Perda de continuidade',detail:'Conhecimento e relacionamentos podem se perder entre gestões.',mitigation:'Registro de compromissos, contatos e próximos passos.',owner:'A definir pela gestão',prob:'Não informada',impact:'Não informado',status:'Monitorar'},{title:'Concentração de receitas',detail:'Participação de eventos e produtos nas entradas cresceu de 59,7% (2024) para 79,2% (2025).',mitigation:'Diversificar receitas recorrentes e monitorar composição financeira.',owner:'VPGG',prob:'Evidência histórica',impact:'Estratégico',status:'Acompanhar'},{title:'Dependência de relações individuais',detail:'Articulações sem registro e próximo passo podem perder continuidade.',mitigation:'Formalizar histórico, responsável, encaminhamento e prazo.',owner:'A definir pela gestão',prob:'Não informada',impact:'Não informado',status:'Monitorar'},{title:'Atividades sem responsável ou prazo',detail:'Entregas sem atribuição clara podem não avançar.',mitigation:'Revisão quinzenal das pendências e definição de responsável.',owner:'A definir pela gestão',prob:'A verificar',impact:'Operacional',status:'Monitorar'},{title:'Entregas incompatíveis com capacidade',detail:'Plano pode exceder a disponibilidade real de pessoas.',mitigation:'Aplicar cenários de capacidade e suspender entregas secundárias quando necessário.',owner:'PresEx',prob:'Dependente da equipe',impact:'Operacional',status:'Monitorar'}];const [risks,setRisks]=useState(()=>persist.risks||defaults);useEffect(()=>setPersist((p:any)=>({...p,risks})),[risks]);return <><PageHead kicker="GOVERNANÇA · CONTINGÊNCIA" title="Riscos e capacidade operacional" desc="Riscos identificados na proposta e controles configuráveis. Probabilidades não documentadas permanecem explicitamente sem classificação."/><div className="capacity-model"><div><span>0 líderes</span><b>Cenário crítico</b><p>Diretor assume entregas essenciais; ações secundárias são suspensas ou adiadas.</p></div><div><span>1 líder</span><b>Capacidade reduzida</b><p>Diretor e líder compartilham execução, com escopo restrito às prioridades.</p></div><div><span>2 líderes</span><b>Cenário intermediário</b><p>Distribuição de entregas, com apoio à frente descoberta.</p></div><div><span>3 líderes</span><b>Cenário completo</b><p>Frentes distribuídas e roadmap planejado, com integração executiva.</p></div></div><div className="risk-list">{risks.map((r:any,i:number)=><div className="risk-card" key={r.title}><div className="risk-num">{String(i+1).padStart(2,'0')}</div><div className="risk-main"><h3>{r.title}</h3><p>{r.detail}</p><div className="risk-mitigation"><b>Mitigação</b><span>{r.mitigation}</span></div></div><div className="risk-fields">{mode==='management'?<><label>Probabilidade<input value={r.prob} onChange={e=>setRisks((old:any[])=>old.map(x=>x.title===r.title?{...x,prob:e.target.value}:x))}/></label><label>Impacto<input value={r.impact} onChange={e=>setRisks((old:any[])=>old.map(x=>x.title===r.title?{...x,impact:e.target.value}:x))}/></label><label>Responsável<input value={r.owner} onChange={e=>setRisks((old:any[])=>old.map(x=>x.title===r.title?{...x,owner:e.target.value}:x))}/></label><label>Status<select value={r.status} onChange={e=>setRisks((old:any[])=>old.map(x=>x.title===r.title?{...x,status:e.target.value}:x))}>{['Monitorar','Acompanhar','Mitigação em curso','Mitigado','Escalar'].map(s=><option key={s}>{s}</option>)}</select></label></>:<><span className="tag gray">Probabilidade: {r.prob}</span><span className="tag gray">Impacto: {r.impact}</span><span className="tag gray">{r.owner}</span></>}</div></div>)}</div></>}
function GovernancePage({mode,persist,setPersist}:any){const [records,setRecords]=useState<any[]>(()=>persist.governance||[]);const [meeting,setMeeting]=useState({date:'',title:'',decisions:'',pending:'',owner:'A definir pela gestão',due:''});useEffect(()=>setPersist((p:any)=>({...p,governance:records})),[records]);const add=()=>{if(!meeting.title.trim())return;setRecords((r:any[])=>[{...meeting,id:Date.now()},...r]);setMeeting({date:'',title:'',decisions:'',pending:'',owner:'A definir pela gestão',due:''})};return <><PageHead kicker="GOVERNANÇA · CONTINUIDADE INSTITUCIONAL" title="Governança e prestação de contas" desc="Ritos quinzenais, mensais e trimestrais dos roadmaps; registro de decisões, pendências e transição."/><div className="three-col governance-cadence">{[{cad:'Quinzenal',title:'Acompanhamento operacional',desc:'Contatos, encaminhamentos, status, prazos e pendências.'},{cad:'Mensal',title:'Revisão das frentes',desc:'Agenda, carteira, receita, contrapartidas, oportunidades e riscos.'},{cad:'Trimestral',title:'Indicadores e prioridades',desc:'Metas, execução, resultados, capacidade e decisões de ajuste.'}].map(x=><div className="cadence-card" key={x.cad}><span>{x.cad}</span><h3>{x.title}</h3><p>{x.desc}</p></div>)}</div><div className="two-col section-gap"><div className="panel"><SectionTitle title="Registrar reunião ou decisão" desc="O registro fica no navegador até exportação."/><div className="form-grid"><label>Data<input type="date" value={meeting.date} onChange={e=>setMeeting({...meeting,date:e.target.value})}/></label><label>Título / rito<input value={meeting.title} onChange={e=>setMeeting({...meeting,title:e.target.value})} placeholder="Ex.: revisão mensal de indicadores"/></label><label className="span2">Decisões tomadas<textarea value={meeting.decisions} onChange={e=>setMeeting({...meeting,decisions:e.target.value})} placeholder="Decisões, justificativas e revisões..."/></label><label className="span2">Pendências<textarea value={meeting.pending} onChange={e=>setMeeting({...meeting,pending:e.target.value})} placeholder="Pendências e próximos encaminhamentos..."/></label><label>Responsável<input value={meeting.owner} onChange={e=>setMeeting({...meeting,owner:e.target.value})}/></label><label>Prazo de acompanhamento<input type="date" value={meeting.due} onChange={e=>setMeeting({...meeting,due:e.target.value})}/></label></div><button className="btn-primary" onClick={add} disabled={mode!=='management'||!meeting.title.trim()}><Save size={15}/> Registrar decisão</button>{mode!=='management'&&<p className="source-note">Alterne para “Gestão local” para habilitar novos registros.</p>}</div><div className="panel"><SectionTitle title="Histórico de registros" desc={`${records.length} registros locais`}/>{records.length===0?<div className="empty-state slim"><ClipboardCheck size={22}/><b>Nenhum registro de governança</b><p>Registre reuniões, decisões e pendências no modo gestão.</p></div>:<div className="meeting-list">{records.map(r=><div key={r.id} className="meeting-item"><span className="date-chip">{r.date?fmtDate(r.date):'Sem data'}</span><div><b>{r.title}</b><small>{r.owner} · Prazo {fmtDate(r.due)}</small>{r.decisions&&<p><b>Decisões:</b> {r.decisions}</p>}{r.pending&&<p><b>Pendências:</b> {r.pending}</p>}</div></div>)}</div>}</div></div><div className="callout section-gap">Princípio de continuidade: todo compromisso deve manter histórico, responsável, prazo, status e próximo passo, evitando que a troca de gestão interrompa relações estratégicas.</div></>}
function SourcesPage(){const links=(source as any).links;return <><PageHead kicker="SISTEMA · RASTREABILIDADE" title="Fontes, auditoria e limitações" desc="Registro das fontes usadas para compor o dashboard e das lacunas que precisam ser resolvidas antes da operação real."/><div className="source-grid"><div className="panel"><SectionTitle title="Arquivos examinados" desc="Materiais anexados nesta conversa."/><div className="file-source"><div className="file-icon">PDF</div><div><b>Proposta Eleitoral-V4.pdf</b><p>10 páginas · diagnóstico histórico, riscos, três marcos, metodologias e indicadores.</p><span className="tag source">Fonte narrativa principal</span></div></div>{['Roadmap_FEJEPAR_Ensino_Superior_2027.xlsx','Roadmap_FEJEPAR_Mercado_2027.xlsx','Roadmap_FEJEPAR_Governamental_2027.xlsx'].map(n=><div className="file-source" key={n}><div className="file-icon xlsx">XLSX</div><div><b>{n}</b><p>Abas de roadmap, carteira/mapa, instruções, painel e ritos de governança.</p><span className="tag source">18 atividades importadas</span></div></div>)}<div className="file-source"><div className="file-icon xlsx">XLSX</div><div><b>FEJEPAR_Inteligencia_Financeira_Oficial_Funcional.xlsx</b><p>Base consolidada de movimentações 2019–2025; classificação de receita de “Eventos e produtos”.</p><span className="tag source">Referência financeira complementar</span></div></div></div><div className="panel"><SectionTitle title="Validações e lacunas" desc="Transparência sobre o que é dado e o que ainda precisa de confirmação."/><div className="audit-list">{[{t:'Histórico 2024–2026',d:'Valores e resultados narrativos extraídos do PDF; não são resultados de 2027.'},{t:'Metas e indicadores',d:'Reproduzidos da proposta, pp. 5, 7 e 9. Resultados atuais ficam em branco até apuração.'},{t:'Carteiras',d:'As abas de carteira contêm linhas-modelo “A definir”/“A mapear”; não há contatos reais importados.'},{t:'Eventos 2027',d:'EDL em março, janela ENEJ julho–setembro e Prêmio em dezembro são referências estimadas, não datas oficiais.'},{t:'Responsáveis',d:'Os nomes e funções vêm das planilhas; lacunas devem ser atribuídas pela gestão.'},{t:'Privacidade',d:'Não há autenticação. Não publicar o modo local com dados internos nem usar como sistema multiusuário.'}].map(x=><div key={x.t}><CheckCircle2 size={16}/><p><b>{x.t}</b><span>{x.d}</span></p></div>)}</div></div></div><div className="panel section-gap"><SectionTitle title={`Hyperlinks encontrados no PDF (${links.length})`} desc="Destinos extraídos dos hyperlinks reais do documento. O registro de destino não significa que o conteúdo foi acessado ou validado."/><div className="links-list">{links.map((l:any,i:number)=><a key={i} href={l.url} target="_blank" rel="noreferrer"><span className="link-page">p. {l.page}</span><span className="link-url">{l.url}</span><ExternalLink size={14}/></a>)}</div><p className="source-note">Os links do Google Drive/Sheets exigem permissões do proprietário. Nesta execução, os arquivos presentes no ZIP foram examinados localmente; não se afirma que todos os destinos externos foram abertos. O PDF contém um hyperlink duplicado/malformado na página 3, registrado sem corrigir o destino.</p></div><div className="panel section-gap"><SectionTitle title="Notas de implementação" desc="Stack e limites atuais."/><div className="three-col"><div className="tech-note"><b>React + TypeScript + Vite</b><p>Interface modular, responsiva, com gráficos e rotas por estado de navegação.</p></div><div className="tech-note"><b>Persistência local</b><p>localStorage neste navegador; exportação JSON/CSV e importação de backup JSON. Sem backend.</p></div><div className="tech-note"><b>Próxima etapa para produção</b><p>Autenticação, autorização por perfil, banco compartilhado, trilha de auditoria no servidor e revisão de privacidade.</p></div></div></div></>}
function NewTaskModal({onClose,onSave}:any){const [form,setForm]=useState({front:'Ensino Superior',code:'CUSTOM-'+Date.now().toString().slice(-4),step:'Ciclo contínuo',activity:'',owner:'A definir pela gestão',start:'',end:'',priority:'Média',status:'Não iniciado',deliverable:''});return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><h2>Nova atividade</h2><button className="icon-btn" onClick={onClose}><X size={18}/></button></div><div className="form-grid"><label>Frente<select value={form.front} onChange={e=>setForm({...form,front:e.target.value})}>{Object.values(fronts).map((x:any)=><option key={x}>{x}</option>)}</select></label><label>Etapa / ciclo<input value={form.step} onChange={e=>setForm({...form,step:e.target.value})}/></label><label className="span2">Atividade / entrega<input value={form.activity} onChange={e=>setForm({...form,activity:e.target.value})} required/></label><label>Responsável<input value={form.owner} onChange={e=>setForm({...form,owner:e.target.value})}/></label><label>Prioridade<select value={form.priority} onChange={e=>setForm({...form,priority:e.target.value})}><option>Alta</option><option>Média</option><option>Baixa</option></select></label><label>Início<input type="date" value={form.start} onChange={e=>setForm({...form,start:e.target.value})}/></label><label>Fim<input type="date" value={form.end} onChange={e=>setForm({...form,end:e.target.value})}/></label><label className="span2">Entregável / evidência<input value={form.deliverable} onChange={e=>setForm({...form,deliverable:e.target.value})}/></label></div><div className="modal-actions"><button className="btn-secondary" onClick={onClose}>Cancelar</button><button className="btn-primary" disabled={!form.activity.trim()} onClick={()=>onSave({'Código':form.code,'Etapa / ciclo':form.step,'Atividade / entrega':form.activity,Responsável:form.owner,Início:form.start,Fim:form.end,Prioridade:form.priority,Status:form.status,'Entregável / evidência':form.deliverable,_front:form.front,_id:form.code})}><Save size={15}/> Criar atividade</button></div><p className="source-note">Atividade personalizada local; exporte os dados para manter backup.</p></div></div>}
createRoot(document.getElementById('root')!).render(<App/>);
